import { describe, expect, it } from 'vitest'
import { create } from 'zustand'
import { useShallow } from 'zustand/react/shallow'
import { shallow } from 'zustand/vanilla/shallow'

const FLAG = Symbol('flag')
const OTHER = Symbol('other')

describe('shallow compares symbol-keyed properties', () => {
  it('is false when a symbol-keyed value differs', () => {
    expect(shallow({ [FLAG]: true }, { [FLAG]: false })).toBe(false)
    expect(shallow({ a: 1, [FLAG]: 1 }, { a: 1, [FLAG]: 2 })).toBe(false)
  })

  it('is true when string and symbol keys all match', () => {
    const shared = { nested: true }
    expect(shallow({ [FLAG]: true }, { [FLAG]: true })).toBe(true)
    expect(
      shallow(
        { a: 1, [FLAG]: shared, [OTHER]: 'x' },
        { [OTHER]: 'x', a: 1, [FLAG]: shared },
      ),
    ).toBe(true)
    expect(shallow({ [FLAG]: { nested: true } }, { [FLAG]: { nested: true } })).toBe(
      false,
    )
  })

  it('is false when the symbol keys differ', () => {
    expect(shallow({ [FLAG]: 1 }, { [OTHER]: 1 })).toBe(false)
    expect(shallow({ [FLAG]: undefined }, { [OTHER]: undefined })).toBe(false)
    expect(shallow({ a: 1 }, { a: 1, [FLAG]: 1 })).toBe(false)
    expect(shallow({ a: 1, [FLAG]: 1 }, { a: 1 })).toBe(false)
    expect(shallow({ [FLAG]: 1 }, { [FLAG]: 1, [OTHER]: 2 })).toBe(false)
  })

  it('keeps string-key and collection behavior unchanged', () => {
    expect(shallow({ a: 1, b: 2 }, { b: 2, a: 1 })).toBe(true)
    expect(shallow({ a: undefined }, { b: 1 })).toBe(false)
    expect(shallow({ a: 1 }, { a: 1, b: 2 })).toBe(false)
    expect(shallow({ a: {} }, { a: {} })).toBe(false)
    expect(shallow([1, 2], [1, 2])).toBe(true)
    expect(shallow([1, 2], [2, 1])).toBe(false)
    expect(shallow(new Set([1, 2]), new Set([2, 1]))).toBe(true)
    expect(shallow(new Map([['a', 1]]), new Map([['a', 2]]))).toBe(false)
  })

  it('lets useShallow re-render when only a symbol-keyed value changes', () => {
    type Flags = { [FLAG]: boolean; name: string }
    const useStore = create<{ flags: Flags }>(() => ({
      flags: { [FLAG]: false, name: 'n' },
    }))
    let renders = 0
    const View = () => {
      const flags = useStore(useShallow((s) => s.flags))
      renders++
      return <div>flag:{String(flags[FLAG])}</div>
    }
    render(<View />)
    expect(screen.getByText('flag:false')).toBeInTheDocument()
    act(() => {
      useStore.setState({ flags: { [FLAG]: true, name: 'n' } })
    })
    expect(screen.getByText('flag:true')).toBeInTheDocument()
    const before = renders
    act(() => {
      useStore.setState({ flags: { [FLAG]: true, name: 'n' } })
    })
    expect(renders).toBe(before)
  })
})

