import { describe, expect, it, vi } from 'vitest'
import { createStore } from 'zustand/vanilla'

type State = { n: number }
const makeStore = () => createStore<State>(() => ({ n: 0 }))

describe('subscription changes made while listeners are being notified', () => {
  it('does not call a listener subscribed during the notification until the next update', () => {
    const store = makeStore()
    const late = vi.fn()
    let added = false
    store.subscribe(() => {
      if (!added) {
        added = true
        store.subscribe(late)
      }
    })
    store.setState({ n: 1 })
    expect(late).not.toHaveBeenCalled()
    store.setState({ n: 2 })
    expect(late).toHaveBeenCalledTimes(1)
    expect(late).toHaveBeenCalledWith({ n: 2 }, { n: 1 })
  })

  it('calls a re-armed one-shot listener once per update', () => {
    const store = makeStore()
    const seen: number[] = []
    const once = (fn: (state: State) => void) => {
      const unsubscribe = store.subscribe((state) => {
        unsubscribe()
        fn(state)
      })
    }
    const handler = (state: State) => {
      seen.push(state.n)
      // guard so a broken store cannot loop forever
      if (seen.length < 20) once(handler)
    }
    once(handler)
    store.setState({ n: 1 })
    expect(seen).toEqual([1])
    store.setState({ n: 2 })
    expect(seen).toEqual([1, 2])
  })

  it('calls a listener that re-subscribes itself once per update', () => {
    const store = makeStore()
    let calls = 0
    let unsubscribe = () => {}
    const listener = () => {
      calls++
      unsubscribe()
      // guard so a broken store cannot loop forever
      if (calls < 20) unsubscribe = store.subscribe(listener)
    }
    unsubscribe = store.subscribe(listener)
    store.setState({ n: 1 })
    expect(calls).toBe(1)
    store.setState({ n: 2 })
    expect(calls).toBe(2)
  })

  it('does not call a listener that an earlier listener unsubscribed', () => {
    const store = makeStore()
    const order: string[] = []
    let unsubscribeSecond = () => {}
    store.subscribe(() => {
      order.push('first')
      unsubscribeSecond()
    })
    const second = vi.fn(() => {
      order.push('second')
    })
    unsubscribeSecond = store.subscribe(second)
    store.subscribe(() => {
      order.push('third')
    })
    store.setState({ n: 1 })
    expect(second).not.toHaveBeenCalled()
    expect(order).toEqual(['first', 'third'])
    store.setState({ n: 2 })
    expect(second).not.toHaveBeenCalled()
  })

  it('does not call a listener subscribed in place of one removed earlier in the same notification', () => {
    const store = makeStore()
    const order: string[] = []
    let swapped = false
    let unsubscribeOld = () => {}
    store.subscribe(() => {
      order.push('first')
      if (!swapped) {
        swapped = true
        unsubscribeOld()
        store.subscribe(() => {
          order.push('replacement')
        })
      }
    })
    unsubscribeOld = store.subscribe(() => {
      order.push('old')
    })
    store.setState({ n: 1 })
    expect(order).toEqual(['first'])
    store.setState({ n: 2 })
    expect(order).toEqual(['first', 'first', 'replacement'])
  })

  it('keeps normal notification order, arguments and unsubscribe', () => {
    const store = makeStore()
    const calls: [string, State, State][] = []
    const unsubscribeA = store.subscribe((s, p) => calls.push(['a', s, p]))
    store.subscribe((s, p) => calls.push(['b', s, p]))
    store.setState({ n: 1 })
    expect(calls).toEqual([
      ['a', { n: 1 }, { n: 0 }],
      ['b', { n: 1 }, { n: 0 }],
    ])
    unsubscribeA()
    store.setState({ n: 2 })
    expect(calls.slice(2)).toEqual([['b', { n: 2 }, { n: 1 }]])
    const current = store.getState()
    store.setState(current)
    expect(calls).toHaveLength(3)
  })
})

