import { act, render, screen } from '@testing-library/react'
import { renderToString } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import { create, useStore } from 'zustand'
import { createStore } from 'zustand/vanilla'

type Temp = { celsius: number; label: string }

// An external store that only implements getState and subscribe.
const makeExternalStore = (initial: Temp) => {
  type Listener = (state: Temp, prevState: Temp) => void
  let state = initial
  const listeners = new Set<Listener>()
  return {
    getState: () => state,
    subscribe: (listener: Listener) => {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    set: (next: Partial<Temp>) => {
      const prevState = state
      state = { ...state, ...next }
      listeners.forEach((listener) => listener(state, prevState))
    },
  }
}

const textOf = (html: string) => {
  const container = document.createElement('div')
  container.innerHTML = html
  return container.textContent
}

describe('useStore server rendering', () => {
  it('server-renders a store without getInitialState using its current state', () => {
    const external = makeExternalStore({ celsius: 21, label: 'office' })
    external.set({ celsius: 23 })

    function Reading() {
      const celsius = useStore(external, (s) => s.celsius)
      return <p>reading: {celsius}</p>
    }
    function Whole() {
      const state = useStore(external)
      return (
        <p>
          whole: {state.label} {state.celsius}
        </p>
      )
    }

    let html = ''
    expect(() => {
      html = renderToString(
        <div>
          <Reading />
          <Whole />
        </div>,
      )
    }).not.toThrow()
    expect(textOf(html)).toBe('reading: 23whole: office 23')
  })

  it('still server-renders the initial state of zustand stores', () => {
    const vanilla = createStore<Temp>(() => ({ celsius: 5, label: 'fridge' }))
    const useBound = create<Temp>(() => ({ celsius: -18, label: 'freezer' }))
    vanilla.setState({ celsius: 9 })
    useBound.setState({ celsius: -2 })

    function Readings() {
      const a = useStore(vanilla, (s) => s.celsius)
      const b = useBound((s) => s.celsius)
      return (
        <p>
          a={a};b={b}
        </p>
      )
    }

    expect(textOf(renderToString(<Readings />))).toBe('a=5;b=-18')
  })

  it('renders and updates on the client as before', () => {
    const external = makeExternalStore({ celsius: 1, label: 'garden' })
    const vanilla = createStore<Temp>(() => ({ celsius: 40, label: 'oven' }))
    vanilla.setState({ celsius: 180 })

    function Readings() {
      const a = useStore(external, (s) => s.celsius)
      const b = useStore(vanilla, (s) => s.celsius)
      return (
        <p>
          a={a};b={b}
        </p>
      )
    }

    render(<Readings />)
    expect(screen.getByText('a=1;b=180')).toBeInTheDocument()
    act(() => external.set({ celsius: 2 }))
    act(() => vanilla.setState({ celsius: 200 }))
    expect(screen.getByText('a=2;b=200')).toBeInTheDocument()
  })
})

import { useCallback, useState } from 'react'
import { act, fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { create, useStore } from 'zustand'
import { createStore } from 'zustand/vanilla'

type Cart = {
  items: { sku: string; price: number; qty: number }[]
  coupon: string
  opened: number
}

const initialCart = (): Cart => ({
  items: [
    { sku: 'a', price: 3, qty: 2 },
    { sku: 'b', price: 5, qty: 1 },
  ],
  coupon: '',
  opened: 0,
})

describe('useStore selector caching', () => {
  it('does not re-run an unchanged selector when the component re-renders', () => {
    const cart = createStore<Cart>(initialCart)
    let calls = 0
    const selectTotal = (s: Cart) => {
      calls++
      return s.items.reduce((sum, i) => sum + i.price * i.qty, 0)
    }

    function Total() {
      const [clicks, setClicks] = useState(0)
      const total = useStore(cart, selectTotal)
      return (
        <button onClick={() => setClicks((c) => c + 1)}>
          total {total} clicks {clicks}
        </button>
      )
    }

    render(<Total />)
    expect(screen.getByRole('button')).toHaveTextContent('total 11 clicks 0')
    expect(calls).toBe(1)

    fireEvent.click(screen.getByRole('button'))
    fireEvent.click(screen.getByRole('button'))
    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByRole('button')).toHaveTextContent('total 11 clicks 3')
    expect(calls).toBe(1)
  })

  it('re-runs the selector once per state change and re-renders only when the slice changes', () => {
    const useCart = create<Cart>(initialCart)
    let calls = 0
    let renders = 0
    const selectCount = (s: Cart) => {
      calls++
      return s.items.length
    }

    function Count() {
      const count = useCart(selectCount)
      renders++
      return <p>items: {count}</p>
    }

    render(<Count />)
    expect(screen.getByText('items: 2')).toBeInTheDocument()
    expect(calls).toBe(1)
    expect(renders).toBe(1)

    act(() => useCart.setState({ opened: 1 }))
    expect(calls).toBe(2)
    expect(renders).toBe(1)

    act(() =>
      useCart.setState((s) => ({
        items: [...s.items, { sku: 'c', price: 1, qty: 1 }],
      })),
    )
    expect(screen.getByText('items: 3')).toBeInTheDocument()
    expect(calls).toBe(3)
    expect(renders).toBe(2)
  })

  it('uses a new selector immediately when it changes', () => {
    const useCart = create<Cart>(initialCart)
    let calls = 0

    function Qty({ sku }: { sku: string }) {
      const [tick, setTick] = useState(0)
      const selectQty = useCallback(
        (s: Cart) => {
          calls++
          return s.items.find((i) => i.sku === sku)?.qty ?? 0
        },
        [sku],
      )
      const qty = useCart(selectQty)
      return (
        <button onClick={() => setTick((t) => t + 1)}>
          {sku}={qty} tick {tick}
        </button>
      )
    }

    const { rerender } = render(<Qty sku="a" />)
    expect(screen.getByRole('button')).toHaveTextContent('a=2 tick 0')
    expect(calls).toBe(1)

    rerender(<Qty sku="b" />)
    expect(screen.getByRole('button')).toHaveTextContent('b=1 tick 0')
    expect(calls).toBe(2)

    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByRole('button')).toHaveTextContent('b=1 tick 1')
    expect(calls).toBe(2)

    rerender(<Qty sku="z" />)
    expect(screen.getByRole('button')).toHaveTextContent('z=0 tick 1')
  })

  it('keeps inline selectors and whole-state reads working', () => {
    const useCart = create<Cart>(initialCart)

    function Summary({ factor }: { factor: number }) {
      const scaled = useCart((s) => s.items.length * factor)
      const state = useCart()
      return (
        <p>
          scaled {scaled} coupon [{state.coupon}]
        </p>
      )
    }

    const { rerender } = render(<Summary factor={1} />)
    expect(screen.getByText('scaled 2 coupon []')).toBeInTheDocument()
    rerender(<Summary factor={10} />)
    expect(screen.getByText('scaled 20 coupon []')).toBeInTheDocument()
    act(() => useCart.setState({ coupon: 'SAVE' }))
    expect(screen.getByText('scaled 20 coupon [SAVE]')).toBeInTheDocument()
    act(() => useCart.setState({ items: [] }))
    expect(screen.getByText('scaled 0 coupon [SAVE]')).toBeInTheDocument()
  })

  it('follows a different store passed to useStore', () => {
    const first = createStore<Cart>(initialCart)
    const second = createStore<Cart>(() => ({ ...initialCart(), items: [] }))
    const selectCount = (s: Cart) => s.items.length

    function Count({ store }: { store: typeof first }) {
      return <p>count {useStore(store, selectCount)}</p>
    }

    const { rerender } = render(<Count store={first} />)
    expect(screen.getByText('count 2')).toBeInTheDocument()
    rerender(<Count store={second} />)
    expect(screen.getByText('count 0')).toBeInTheDocument()
    act(() =>
      second.setState({ items: [{ sku: 'x', price: 1, qty: 1 }] }),
    )
    expect(screen.getByText('count 1')).toBeInTheDocument()
  })
})

