    expect(typeof (traditional as any).bindStoreWithEqualityFn).toBe(
      'function',
    )
  })

  it('returns a hook that reads and follows the existing store', () => {
    const api = createStore<State>(initial)
    const useBound = bindStoreWithEqualityFn(api)
    function Count() {
      const count = useBound((s: State) => s.count)
      return <div>count: {count}</div>
    }
    render(<Count />)
    expect(screen.getByText('count: 0')).toBeInTheDocument()

    act(() => api.setState({ count: 1 }))
    expect(screen.getByText('count: 1')).toBeInTheDocument()
  })

  it('exposes getState, setState, subscribe and getInitialState of that same store', () => {
    const api = createStore<State>(initial)
    const useBound = bindStoreWithEqualityFn(api)
    function Count() {
      const count = useBound((s: State) => s.count)
      return <div>count: {count}</div>
    }
    render(<Count />)

    act(() => useBound.setState({ count: 2 }))
    expect(api.getState().count).toBe(2)
    expect(screen.getByText('count: 2')).toBeInTheDocument()

    api.setState({ count: 3 })
    expect(useBound.getState()).toBe(api.getState())
    expect(useBound.getInitialState()).toBe(api.getInitialState())

    const listener = vi.fn()
    const unsubscribe = useBound.subscribe(listener)
    act(() => api.setState({ count: 4 }))
    expect(listener).toHaveBeenCalledTimes(1)
    expect(listener.mock.calls[0]![0].count).toBe(4)
    unsubscribe()
    act(() => api.setState({ count: 5 }))
    expect(listener).toHaveBeenCalledTimes(1)
  })

