    const api = createStore<State>(initial)
    const useBound = bindStoreWithEqualityFn(api)
    function Whole() {
      const state = useBound() as State
      return <div>whole: {state.count}</div>
    }
    render(<Whole />)
    act(() => api.setState({ count: 7 }))
    expect(screen.getByText('whole: 7')).toBeInTheDocument()
